<?php

namespace App\Services\Billing;

use Illuminate\Support\Facades\Cache;
use Illuminate\Support\Facades\Log;
use KHQR\BakongKHQR;

/**
 * Server-side checks for dynamic (Bakong) KHQR payments.
 *
 * When a QR is generated we remember which invoice and amount its md5 belongs to.
 * When the cashier records the payment we verify that:
 *   1. the md5 was generated by us for THIS invoice and THIS amount,
 *   2. Bakong confirms the transaction was paid.
 * This stops a payment being recorded with an md5 copied from another transaction.
 */
class KhqrVerifier
{
    private const CACHE_PREFIX = 'khqr:';
    private const TTL_MINUTES = 60;

    public static function isMd5(?string $value): bool
    {
        return is_string($value) && preg_match('/^[a-f0-9]{32}$/i', $value) === 1;
    }

    public function remember(string $md5, ?int $invoiceId, float $amount, string $currency): void
    {
        Cache::put(self::CACHE_PREFIX . strtolower($md5), [
            'invoice_id' => $invoiceId,
            'amount' => round($amount, 2),
            'currency' => $currency,
        ], now()->addMinutes(self::TTL_MINUTES));
    }

    /**
     * Returns null when OK, otherwise a bilingual error message.
     */
    public function verifyForInvoice(string $md5, int $invoiceId, float $amount): ?string
    {
        $meta = Cache::get(self::CACHE_PREFIX . strtolower($md5));

        if (!$meta || (int) ($meta['invoice_id'] ?? 0) !== $invoiceId) {
            return 'QR នេះមិនមែនសម្រាប់វិក្កយបត្រនេះទេ ឬផុតកំណត់ហើយ (This QR was not generated for this invoice, or it has expired).';
        }

        if (abs(round($amount, 2) - (float) $meta['amount']) > 0.001) {
            return 'ចំនួនប្រាក់មិនត្រូវនឹង QR ទេ (Amount does not match the generated QR).';
        }

        if (!$this->isPaid($md5)) {
            return 'Bakong មិនទាន់បញ្ជាក់ការទូទាត់នេះទេ (Bakong has not confirmed this payment).';
        }

        return null;
    }

    public function isPaid(string $md5): bool
    {
        $token = config('services.bakong.token');

        if (empty($token) || !self::isMd5($md5)) {
            return false;
        }

        try {
            $response = (new BakongKHQR($token))->checkTransactionByMD5($md5);

            // Bakong API: responseCode 0 = transaction found / successful
            return isset($response['responseCode']) && (int) $response['responseCode'] === 0;
        } catch (\Throwable $e) {
            Log::warning('KHQR status check failed', ['message' => $e->getMessage()]);
            return false;
        }
    }
}
